def metric(data: pd.DataFrame) -> float:
    def f0_chosen(row):
        a0 = row['option_a_ratings'][0]
        b0 = row['option_b_ratings'][0]
        if a0 == b0:
            return None
        return a0 if row['response'] == 0 else b0

    f0_vals = data.apply(f0_chosen, axis=1).dropna()
    if len(f0_vals) == 0:
        return 0.5
    return float(f0_vals.mean())

